'use strict';
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),crypto=require('node:crypto');
const root=path.resolve(__dirname,'..'),arg=process.argv.find(v=>v.startsWith('--dir=')),dir=path.resolve(root,arg?arg.slice(6):'.build-private/admin-preview');
const m=JSON.parse(fs.readFileSync(path.join(dir,'admin-package.json'),'utf8'));
assert.equal(m.kind,'modus-protected-admin-browser-only');assert.equal(m.project,'modus-2-preview');assert.equal(m.planned_preview_branch,'dev/modus-2-pr52');assert.equal(m.planned_hostname,'dev-modus-2-pr52.modus-2-preview.pages.dev');assert.notEqual(m.planned_preview_branch,'main');
if(process.argv.includes('--reviewed')){assert.equal(m.tracked_source_dirty,false);assert.deepEqual(m.untracked_source_files,[]);assert.equal(m.source_sha,require('node:child_process').execFileSync('git',['rev-parse','HEAD'],{cwd:root,encoding:'utf8'}).trim());}
assert.equal(m.backend,'disabled');assert.equal(m.crossDeviceSync,false);assert.equal(m.ownerApproval,'disabled');assert.equal(m.publishing,'disabled');assert.equal(m.externalAI,'disabled');assert.equal(m.cmsSeedRecords,0);assert.equal(fs.readFileSync(path.join(dir,'cms-seed.json'),'utf8').trim(),'[]');
const actual=fs.readdirSync(dir,{recursive:true}).filter(n=>fs.statSync(path.join(dir,n)).isFile()).sort();assert.deepEqual(actual,[...m.files.map(v=>v.path),'admin-package.json'].sort());
for(const f of m.files){assert(!f.path.includes('..'));const bytes=fs.readFileSync(path.join(dir,f.path));assert.equal(crypto.createHash('sha256').update(bytes).digest('hex'),f.sha256);assert.equal(bytes.length,f.bytes);}
assert(!actual.some(n=>/\.map$|(?:^|\/)(?:content|editorial|docs|tests|functions|\.git)\/|(?:^|\/)\.env/.test(n)));
const texts=actual.filter(n=>!n.endsWith('.png')).map(n=>[n,fs.readFileSync(path.join(dir,n),'utf8')]);
for(const [name,text] of texts)assert(!/sb_(?:publishable|secret)_[A-Za-z0-9_-]{10,}|[a-z0-9-]+\.supabase\.(?:co|in)|-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----|sourceMappingURL=/.test(text),'Forbidden backend/secret/map in '+name);
const paragraphs=JSON.parse(fs.readFileSync(path.join(root,'content/articles.json'),'utf8')).flatMap(a=>[a.intro,...a.sections.map(s=>s[1])]);const normalize=t=>t.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();for(const paragraph of paragraphs){const p=normalize(paragraph);if(p.length>=80)for(const [name,text] of texts)assert(!normalize(text).includes(p),'Private prose included in '+name);}
const headers=fs.readFileSync(path.join(dir,'_headers'),'utf8');assert(headers.startsWith('/*\n'));for(const expected of ["connect-src 'self'","frame-ancestors 'none'","form-action 'none'",'Cache-Control: private, no-store','X-Robots-Tag: noindex'])assert(headers.includes(expected));
for(const name of ['index.html','redaktor.html']){const html=fs.readFileSync(path.join(dir,name),'utf8');assert(html.includes('class="modus-mark"'));assert(html.includes('<script src="admin-app.js" type="module"></script>'));assert(!html.includes('src="editor.js"'));for(const [,asset] of html.matchAll(/(?:href|src)="([^"#]+)"/g)){if(asset==='/'||asset.startsWith('/artikler')||asset.startsWith('http:')||asset.startsWith('https:')||asset.startsWith('data:'))continue;assert(fs.existsSync(path.join(dir,asset)),name+' missing '+asset);}}
console.log('Admin artifact passed: exact manifest, 0 CMS seed, no private prose/SDK credentials/maps/source folders, security headers and complete static resources. Access still requires remote deployment verification.');
